parameters.jsCode:
// Extract clean fields from the incoming email
const email = $input.item.json;

return {
  from: email.from?.value?.[0]?.address || email.from || 'unknown',
  fromName: email.from?.value?.[0]?.name || 'Unknown Sender',
  subject: email.subject || '(no subject)',
  body: email.textPlain || email.textHtml || email.snippet || '',
  threadId: email.threadId,
  messageId: email.id
};

// Parse Groq's response into summary + reply text
const response = $input.item.json;
const text = response.choices?.[0]?.message?.content || '';

const summaryMatch = text.match(/SUMMARY:\s*([\s\S]*?)(?=REPLY:|$)/i);
const replyMatch = text.match(/REPLY:\s*([\s\S]*)/i);

const summary = summaryMatch ? summaryMatch[1].trim() : 'Summary unavailable';
const reply = replyMatch ? replyMatch[1].trim() : text.trim();

let needsHuman = reply.includes('[NEEDS HUMAN INPUT');

// HARD SAFETY NET - forces human review regardless of what the AI decided
const originalEmail = $('Extract Email Fields1').item.json;
const fullText = (originalEmail.subject + ' ' + originalEmail.body).toLowerCase();

const sensitiveKeywords = [
  'password', 'otp', 'one time password', 'login credential', 'username and password',
  'ssn', 'social security', 'aadhaar', 'pan card', 'bank account', 'account number',
  'ifsc', 'salary', 'confidential', 'budget', 'invoice', 'refund', 'discount',
  'contract', 'agreement', 'legal', 'lawsuit', 'nda', 'non-disclosure',
  'medical', 'health record', 'resignation', 'termination', 'offer letter'
];

const matchedKeyword = sensitiveKeywords.find(keyword => fullText.includes(keyword));
if (matchedKeyword) {
  needsHuman = true;
}

return {
  ...originalEmail,
  aiSummary: summary,
  aiReply: reply,
  needsHuman,
  flaggedKeyword: matchedKeyword || null
};
